// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetModelCard Model card of the active model
	// (GET /api/v1/model)
	GetModelCard(ctx context.Context, request GetModelCardRequestObject) (GetModelCardResponseObject, error)
	// ListOperators Band counts per operator as of a replay day
	// (GET /api/v1/operators)
	ListOperators(ctx context.Context, request ListOperatorsRequestObject) (ListOperatorsResponseObject, error)
	// GetPlayer Player case header, score and reasons
	// (GET /api/v1/players/{player_id})
	GetPlayer(ctx context.Context, request GetPlayerRequestObject) (GetPlayerResponseObject, error)
	// ListPlayerReviews All reviews of this player, newest first
	// (GET /api/v1/players/{player_id}/reviews)
	ListPlayerReviews(ctx context.Context, request ListPlayerReviewsRequestObject) (ListPlayerReviewsResponseObject, error)
	// CreateReview Save a review
	// (POST /api/v1/players/{player_id}/reviews)
	CreateReview(ctx context.Context, request CreateReviewRequestObject) (CreateReviewResponseObject, error)
	// ListPlayerSessions Sessions up to as_of_day, newest first
	// (GET /api/v1/players/{player_id}/sessions)
	ListPlayerSessions(ctx context.Context, request ListPlayerSessionsRequestObject) (ListPlayerSessionsResponseObject, error)
	// GetPlayerTimeline Daily activity from day 0 up to as_of_day
	// (GET /api/v1/players/{player_id}/timeline)
	GetPlayerTimeline(ctx context.Context, request GetPlayerTimelineRequestObject) (GetPlayerTimelineResponseObject, error)
	// GetQueue Review queue as of a replay day
	// (GET /api/v1/queue)
	GetQueue(ctx context.Context, request GetQueueRequestObject) (GetQueueResponseObject, error)
	// GetReplay Replay range and active model
	// (GET /api/v1/replay)
	GetReplay(ctx context.Context, request GetReplayRequestObject) (GetReplayResponseObject, error)
	// GetHealth Liveness and dependency status
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// IngestEvents Submit a batch of events for one player and get the current score
	// (POST /ingest/v1/events)
	IngestEvents(ctx context.Context, request IngestEventsRequestObject) (IngestEventsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

